// 1. Publish Post
POST /api/v1/posts
Request:
{
  "content": "Launching our new distributed caching layer today!",
  "media_ids": ["med_8812"]
}
Response (201 Created):
{
  "post_id": "718293910293847102",
  "author_id": "440192",
  "fanout_mode": "PUSH_ASYNC",
  "created_at": "2026-09-30T16:25:00Z"
}

// 2. Fetch Cursor-Paginated Home Timeline
GET /api/v1/feed?cursor=718293910293847102&limit=20
Response (200 OK):
{
  "items": [
    {
      "post_id": "718293910293847055",
      "author": { "user_id": "9910", "handle": "@system_arch" },
      "content": "Hybrid push-pull avoids celebrity write amplification.",
      "like_count": 412
    }
  ],
  "next_cursor": "718293800112233445"
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY users (PostgreSQL + Redis Cache) {
  [PK ] user_id                BIGINT
  [IDX] handle                 VARCHAR(64)
        follower_count         INT
  [IDX] is_celebrity           BOOLEAN (>= 10k)
        created_at             TIMESTAMPTZ
}

ENTITY follows_graph (Cassandra / Social Graph DB) {
  [PK ] follower_id            BIGINT (Partition)
  [PK ] followee_id            BIGINT (Clustering)
        is_celeb_edge          BOOLEAN
        created_at             TIMESTAMPTZ
}

ENTITY posts (Cassandra + Redis Post Cache) {
  [PK ] post_id                BIGINT (Snowflake)
  [FK ] author_id              BIGINT
        content                VARCHAR(2000)
        media_urls             ARRAY<TEXT>
  [IDX] created_at             TIMESTAMPTZ
}

// Relationships: users --(1 : N (social graph edges))--> follows_graph --(1 : N (publishes posts))--> posts

/*
================================================================================
FLOW 1: HYBRID WRITE & FANOUT PIPELINE
================================================================================
[Author] -> [PostSvc] -> (1) Save to ScyllaDB & ZADD outbox:{authorId}
                      -> (2) Publish PostCreatedEvent to Kafka
[FanoutWorker]        <- (3) Consume PostCreatedEvent
                      -> (4) If author.isCelebrity() (>50K followers): STOP (No Push)
                      -> (5) Else: Fetch active followers & Pipeline ZADD inbox:{followerId}

================================================================================
FLOW 2: HYBRID READ, K-WAY MERGE & BULK HYDRATION
================================================================================
[Reader] -> [FeedSvc] -> (1) Async Parallel:
                             a) ZREVRANGEBYSCORE inbox:{userId} (cursor, -inf, 20)
                             b) Fetch followed Celeb IDs -> Pipeline ZREVRANGEBYSCORE outbox:{celebId}
                      -> (2) K-Way Merge in Memory (Sort by Snowflake ID / Rank Score)
                      -> (3) Batch MGET Post & User Metadata from L2 Redis Cache
                      -> (4) On Partial Miss -> Read ScyllaDB & Backfill Cache -> Return DTO
*/

package com.sdi.newsfeed.service;

import com.sdi.newsfeed.domain.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;

public class HybridNewsFeedEngine {

    private static final int MAX_TIMELINE_SIZE = 800;
    private static final int CELEBRITY_THRESHOLD = 50_000;

    private final RedisTimelineClient redisClient;
    private final SocialGraphClient graphClient;
    private final PostHydrationService hydrationService;

    public HybridNewsFeedEngine(
        RedisTimelineClient redisClient,
        SocialGraphClient graphClient,
        PostHydrationService hydrationService
    ) {
        this.redisClient = redisClient;
        this.graphClient = graphClient;
        this.hydrationService = hydrationService;
    }

    /**
     * FLOW 1: Kafka Consumer Worker handling Hybrid Fanout-on-Write
     */
    public void onPostCreatedEvent(PostEntity post, UserEntity author) {
        // 1. Always append to author's own outbox (used for profile page & celebrity pull)
        redisClient.zaddAndTrim(
            "outbox:" + author.userId(),
            post.postId(),
            new TimelineItem(post.postId(), author.userId(), post.createdAt().toEpochMilli(), 0.0),
            200
        );

        // 2. Celebrity check: skip fanout-on-write if >= 50,000 followers
        if (author.isCelebrity() || author.followerCount() >= CELEBRITY_THRESHOLD) {
            return;
        }

        // 3. Regular user: stream active followers (active within last 30 days) and pipeline ZADD
        List<Long> activeFollowerIds = graphClient.getActiveFollowers(author.userId());
        TimelineItem item = new TimelineItem(
            post.postId(), author.userId(), post.createdAt().toEpochMilli(), 0.0
        );

        // Batch into chunks of 500 to avoid blocking Redis event loop
        for (int i = 0; i < activeFollowerIds.size(); i += 500) {
            List<Long> batch = activeFollowerIds.subList(
                i, Math.min(i + 500, activeFollowerIds.size())
            );
            redisClient.pipelineZAddAndTrimInboxes(batch, post.postId(), item, MAX_TIMELINE_SIZE);
        }
    }

    /**
     * FLOW 2: Hybrid Timeline Read (Merge Precomputed Inbox + Celebrity Outboxes)
     */
    public FeedResponse getHomeTimeline(long userId, Long cursorPostId, int limit) {
        long maxScoreExclusive = (cursorPostId == null) ? Long.MAX_VALUE : cursorPostId - 1;

        // 1a. Fetch precomputed inbox items asynchronously
        CompletableFuture<List<TimelineItem>> inboxFuture = CompletableFuture.supplyAsync(() ->
            redisClient.zrevrangeByScore("inbox:" + userId, maxScoreExclusive, 0L, limit)
        );

        // 1b. Fetch followed celebrities' outbox items asynchronously
        CompletableFuture<List<TimelineItem>> celebFuture = CompletableFuture.supplyAsync(() -> {
            List<Long> followedCelebIds = graphClient.getFollowedCelebrities(userId);
            if (followedCelebIds.isEmpty()) {
                return Collections.emptyList();
            }
            return redisClient.pipelineZRevRangeOutboxes(followedCelebIds, maxScoreExclusive, 0L, limit);
        });

        // 2. Merge & deduplicate top `limit` items sorted descending by postId (Snowflake)
        List<TimelineItem> mergedTopItems = inboxFuture.thenCombine(celebFuture, (inbox, celebItems) -> {
            Map<Long, TimelineItem> deduped = new HashMap<>();
            inbox.forEach(item -> deduped.put(item.postId(), item));
            celebItems.forEach(item -> deduped.put(item.postId(), item));

            return deduped.values().stream()
                .sorted(Comparator.comparingLong(TimelineItem::postId).reversed())
                .limit(limit)
                .collect(Collectors.toList());
        }).join();

        if (mergedTopItems.isEmpty()) {
            return new FeedResponse(Collections.emptyList(), null, false);
        }

        // 3. Bulk-hydrate Post & Author metadata via L2 Cache + ScyllaDB fallback
        List<Long> postIds = mergedTopItems.stream().map(TimelineItem::postId).toList();
        List<HydratedPostDto> hydratedPosts = hydrationService.bulkHydrate(postIds);

        Long nextCursor = hydratedPosts.get(hydratedPosts.size() - 1).postId();
        return new FeedResponse(hydratedPosts, nextCursor, hydratedPosts.size() == limit);
    }
}
